INSERT INTO `bureau` (`code_bureau`, `label_bureau`, `desc_bureau`, `type_bureau`, `created_at`, `updated_at`) VALUES
('ECOM', 'E-Commerce', NULL, 'Departement', '2024-02-20 17:42:06', '2024-02-20 17:42:06'),
('GI', 'Génie Informatique', '<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong><span lang=\"FR\">Objectifs du Departement</span></strong><span lang=\"FR\">&nbsp;: Le d&eacute;partement a pour objectif de former des &eacute;tudiants capable de r&eacute;aliser tout type de logiciel permettant de r&eacute;soudre un probl&egrave;me pr&eacute;cis. Les &eacute;tudiants form&eacute;s pourront travailler &agrave; leur propre compte (auto-emploi) ou alors pourront dans n&rsquo;importe quelle entreprise de renom.</span></p>', 'Departement', '2024-02-20 05:10:04', '2024-02-20 05:10:04'),
('GIL', 'Génie Logistique', '<p><span lang=\"FR-CM\" style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-ansi-language: FR-CM; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Bienvenue au d&eacute;partement de G&eacute;nie logistique de l\'&Eacute;cole Sup&eacute;rieure de Transport, de Logistique et de Commerce (ESTLC). Notre d&eacute;partement est d&eacute;di&eacute; &agrave; former les futurs professionnels de la logistique, en mettant l\'accent sur l\'acquisition de comp&eacute;tences techniques pointues et la compr&eacute;hension approfondie des d&eacute;fis logistiques contemporains.</span></p>', 'Departement', '2024-02-20 05:14:02', '2024-02-20 05:14:02'),
('GLTCO', 'Enseignements Généreaux', '', 'Departement', NULL, NULL),
('GME', 'Génie Mécatronique', '<p><span style=\"font-size: 12pt; color: rgb(0,0,0); font-style: normal; font-variant: normal;\">Les syst&egrave;mes industriels actuels font partie de beaucoup de secteurs industriels tels que l&rsquo;automobile, l&rsquo;a&eacute;ronautique, l&rsquo;agroalimentaire etc. ; leurs conception et pilotage deviennent de plus en plus complexes. La conception et le pilotage de ces syst&egrave;mes constituent des t&acirc;ches exigeantes et n&eacute;cessitent un ensemble d&rsquo;actions telles que : la conception, la configuration, l&rsquo;installation, la supervision et la commande. Les comp&eacute;tences n&eacute;cessaires &agrave; un pilotage efficace s&rsquo;&eacute;talent de la compr&eacute;hension de l&rsquo;architecture des syst&egrave;mes &agrave; concevoir ou &agrave; piloter jusqu&rsquo;au d&eacute;veloppement de nouveaux composants dans les syst&egrave;mes.<br style=\"font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: 2; text-align: -webkit-auto; text-indent: 0px; text-transform: none; white-space: normal; widows: 2; word-spacing: 0px; -webkit-text-size-adjust: auto; -webkit-text-stroke-width: 0px;\"><!--E</body>--></span></p>', 'Departement', '2024-02-20 05:08:27', '2024-02-20 05:08:27'),
('GT', 'Génie des Transports', NULL, 'Departement', '2024-02-20 05:16:56', '2024-02-20 05:16:56'),
('RO', 'Recherche Opérationnelle', NULL, 'Departement', '2024-02-20 05:19:03', '2024-02-20 05:19:03'),
('TTL', 'Enseignements Scientifiques de Base', '', 'Departement', NULL, NULL),
('UFD-TSI', 'Unité de Formation Doctorale en Technologies et Sciences de l\'Innovation', '<p>L\'UFD-TSI est une plateforme d\'excellence d&eacute;di&eacute;e &agrave; l\'innovation technologique et &agrave; la recherche appliqu&eacute;e. En tant que Coordonnateur, ma vision est de faire de cette unit&eacute; &eacute;mergente un centre de r&eacute;f&eacute;rence, aussi bien au Cameroun qu\'&agrave; l\'&eacute;chelle internationale, pour la conception de solutions novatrices face aux d&eacute;fis contemporains.</p>\r\n<p>L\'UFD-TSI envisage de d&eacute;velopper des collaborations et des partenariats strat&eacute;giques avec des acteurs industriels, acad&eacute;miques et institutionnels, afin de cr&eacute;er des synergies qui renforceront l\'impact de nos recherches. Ce r&eacute;seau de partenaires permettra d\'aligner nos projets sur les besoins r&eacute;els de la soci&eacute;t&eacute; et de l\'&eacute;conomie, tout en favorisant la recherche, le d&eacute;veloppement et l\'innovation.</p>\r\n<p>Gr&acirc;ce &agrave; la qualit&eacute; de notre formation, &agrave; nos projets de recherche ambitieux, et &agrave; notre ouverture vers le monde industriel et acad&eacute;mique, nous aspirons &agrave; cr&eacute;er un impact durable, en contribuant au d&eacute;veloppement du Cameroun, de l\'Afrique centrale, et au-del&agrave;.</p>', 'Departement', '2025-05-05 20:34:48', '2025-05-05 20:34:48');
